/**
 * The final investment memo, assembled deterministically from the agents' structured results and the CIO's
 * decision. Every sentence either restates an agent's cited claim (keeping its [id] citations) or describes the
 * committee's own rules. Nothing here is generated by an LLM; an optional LLM rewrite of the executive thesis is
 * applied later and only if it passes the numeric and decision guards.
 */
import type { Subject } from "./context";
import type { CioDetails } from "./cio";
import type { ContrarianDetails } from "./contrarian";
import type { FundamentalDetails } from "./fundamental";
import type { IntelligenceDetails } from "./intelligence";
import type { QuantDetails } from "./quant";
import type { RiskDetails } from "./risk";
import { AGENT_NAMES, type AgentId, type AgentResult, type Claim, type Decision, type Intent } from "./schema";
import type { StrategistDetails } from "./strategist";

export interface InvestmentMemo {
  title: string;
  asset: string;
  question: string;
  currentContext: string;
  decision: Decision | null;
  conviction: number;
  timeHorizon: string;
  executiveThesis: string;
  why: string[];
  views: Partial<Record<Exclude<AgentId, "cio">, string>>;
  disagreements: string[];
  scenarios: { bull: string; base: string; bear: string };
  keyCatalysts: string[];
  keyRisks: string[];
  whatWouldChangeOurMind: string[];
  finalDecision: string;
  disclaimers: string[];
}

export const MEMO_DISCLAIMERS = [
  "EquityLens is a research tool. This memo is not personalised investment advice.",
  "No model in EquityLens has shown out-of-sample skill at predicting price direction; decisions summarise evidence under published rules.",
  "Market data comes from Yahoo Finance and other public feeds and may be delayed or contain errors.",
  "Conviction measures how strong and how consistent the evidence is. It is not a probability of profit.",
];

const HORIZON_TEXT: Record<Intent["horizon"], string> = {
  short: "Short term (days to weeks)",
  medium: "Medium term (months to a year)",
  long: "Long term (years)",
  unknown: "Not stated. Quantitative evidence speaks to weeks; fundamentals to quarters and years.",
};

const get = <D>(results: readonly AgentResult[], id: AgentId) => {
  const r = results.find((x) => x.agent === id && x.status !== "failed" && x.view !== "no_view");
  return r ? (r as AgentResult<D>) : undefined;
};

function subjectName(s: Subject, intent: Intent): string {
  if (s.kind === "asset") return s.ticker;
  if (s.kind === "portfolio") return s.source === "saved" ? "Your saved portfolio" : `Proposed portfolio (${s.tickers.join(", ")})`;
  return intent.unresolvedAsset ?? "Indian equity market";
}

/** The strongest cited claims in the direction of the decision (or both directions when it is neutral). */
function pickWhy(results: readonly AgentResult[], d: Omit<CioDetails, "memo">): string[] {
  const dir = d.score === null ? 0 : d.score >= 0.5 ? 1 : d.score <= -0.5 ? -1 : 0;
  const weight = new Map(d.weights.map((w) => [w.agent, w.effectiveWeight]));
  const pool: Array<{ c: Claim; w: number }> = [];
  for (const r of results) {
    if (r.agent === "cio" || r.agent === "contrarian") continue;
    for (const c of r.claims) {
      const s = c.direction === "positive" ? 1 : c.direction === "negative" ? -1 : 0;
      if (dir !== 0 && s !== dir) continue;
      if (dir === 0 && s === 0) continue;
      pool.push({ c, w: weight.get(r.agent) ?? 0 });
    }
  }
  return pool.sort((a, b) => b.w - a.w).slice(0, 3).map((p) => p.c.text);
}

function changeMind(results: readonly AgentResult[], d: Omit<CioDetails, "memo">): string[] {
  const out: string[] = [];
  const q = get<QuantDetails>(results, "quant")?.details;
  if (q?.trend === "uptrend") out.push("A sustained close below the 200-day average would remove the trend support.");
  if (q?.trend === "downtrend") out.push("A sustained close back above a rising 200-day average would weaken the bearish trend case.");
  const risk = get<RiskDetails>(results, "risk")?.details;
  if (risk && (risk.riskLevel === "low" || risk.riskLevel === "medium")) out.push("Risk rising to HIGH (for example, annualised volatility above 35%) would cap the decision.");
  if (risk && (risk.riskLevel === "high" || risk.riskLevel === "extreme")) out.push("Volatility and tail losses falling back to medium levels would lift the risk cap.");
  const f = get<FundamentalDetails>(results, "fundamental");
  if (f && (f.view === "bullish" || f.view === "lean_bullish")) out.push("Reported results showing revenue growth below 5% or shrinking margins would undercut the fundamental case.");
  if (f && (f.view === "bearish" || f.view === "lean_bearish")) out.push("Earnings growth recovering above 15% with stable leverage would improve the fundamental case.");
  const c = get<ContrarianDetails>(results, "contrarian")?.details;
  if (c && c.verdict !== "THESIS SURVIVES" && c.thesisAttacks[0]) out.push(`Resolution of the main challenge: ${c.thesisAttacks[0].attack}`);
  if (d.decision === "INSUFFICIENT DATA") out.push("Availability of the missing data listed below.");
  if (get(results, "intelligence")) out.push("A regulatory action, guidance cut or major corporate event in the news.");
  return out.length ? out : ["New evidence from any of the agents that contradicts the current view."];
}

export function buildMemo(intent: Intent, subject: Subject, results: readonly AgentResult[], d: Omit<CioDetails, "memo">, now: Date): InvestmentMemo {
  const asset = subjectName(subject, intent);
  const st = get<StrategistDetails>(results, "strategist");
  const q = get<QuantDetails>(results, "quant");
  const f = get<FundamentalDetails>(results, "fundamental");
  const intel = get<IntelligenceDetails>(results, "intelligence");
  const risk = get<RiskDetails>(results, "risk");
  const con = get<ContrarianDetails>(results, "contrarian");

  const views: InvestmentMemo["views"] = {};
  for (const r of results) if (r.agent !== "cio") views[r.agent] = r.status === "failed" ? `Did not run successfully: ${r.error ?? "unknown error"}.` : r.conclusion;

  const positives = results.filter((r) => r.agent !== "cio" && (r.view === "bullish" || r.view === "lean_bullish")).map((r) => AGENT_NAMES[r.agent]);
  const negatives = results.filter((r) => r.agent !== "cio" && (r.view === "bearish" || r.view === "lean_bearish")).map((r) => AGENT_NAMES[r.agent]);
  const thesis = d.decision === null
    ? `${d.decisionNote} ${[q?.conclusion, intel?.conclusion, st?.conclusion].filter(Boolean).join(" ")}`.trim()
    : d.decision === "INSUFFICIENT DATA"
      ? `The committee cannot reach a decision on ${asset}. ${d.decisionNote}`
      : `The committee's decision on ${asset} is ${d.decision} with conviction ${d.conviction}/100. ` +
        (positives.length ? `Supportive: ${positives.join(", ")}. ` : "") +
        (negatives.length ? `Cautious: ${negatives.join(", ")}. ` : "") +
        (con ? `Contrarian review: ${con.details?.verdict}. ` : "") +
        (d.overrides.length ? d.overrides.join(" ") : "");

  const stress = risk?.details?.stressTests.filter((s) => s.portfolioReturn !== null).sort((a, b) => (a.portfolioReturn ?? 0) - (b.portfolioReturn ?? 0))[0];
  const scenarios = {
    bull: st?.details?.scenarios?.bull.description
      ? `${st.details?.scenarios.bull.name}: ${st.details?.scenarios.bull.description}${f?.details?.keyStrengths.length ? ` Company strengths: ${f.details?.keyStrengths.slice(0, 2).join("; ")}.` : ""}`
      : f?.details?.keyStrengths.length ? `Strengths hold: ${f.details?.keyStrengths.slice(0, 3).join("; ")}.` : "No bull case could be built from the available evidence.",
    base: st?.details?.scenarios?.base.description ? `${st.details?.scenarios.base.name}: ${st.details?.scenarios.base.description}` : "The current conditions persist; see the agent views.",
    bear: [con?.details?.bearCase, stress ? `Worst tested scenario: ${stress.label}, ${(stress.portfolioReturn! * 100).toFixed(1)}%.` : null].filter(Boolean).join(" ") || "No bear case could be built from the available evidence.",
  };

  const keyRisks = [...new Set([...(risk?.risks ?? []), ...(con?.risks ?? []), ...(q?.risks ?? []), ...(st?.risks ?? [])])].slice(0, 6);
  const keyCatalysts = [...new Set([...(intel?.catalysts ?? []), ...(q?.catalysts ?? [])])].slice(0, 5);
  const ctxBits = [st?.details?.marketRegime ? `Market regime: ${st.details.marketRegime.name}` : null, q?.details?.trend ? `${asset} trend: ${q.details?.trend}` : null, risk ? `risk ${risk.details?.riskLevel.toUpperCase()}` : null].filter(Boolean);

  return {
    title: `Investment committee memo: ${asset}`,
    asset,
    question: intent.query,
    currentContext: ctxBits.length ? `${ctxBits.join("; ")}. Prepared ${now.toISOString().slice(0, 16).replace("T", " ")} UTC.` : `Prepared ${now.toISOString().slice(0, 16).replace("T", " ")} UTC.`,
    decision: d.decision,
    conviction: d.conviction,
    timeHorizon: HORIZON_TEXT[intent.horizon],
    executiveThesis: thesis.trim(),
    why: pickWhy(results, d),
    views,
    disagreements: d.disagreements.map((x) => `${AGENT_NAMES[x.between[0]]} vs ${AGENT_NAMES[x.between[1]]}. ${x.resolution}`),
    scenarios,
    keyCatalysts,
    keyRisks,
    whatWouldChangeOurMind: changeMind(results, d),
    finalDecision: d.decision === null ? d.decisionNote : `${d.decision}. ${d.decisionNote}${d.overrides.length ? ` ${d.overrides.join(" ")}` : ""}`,
    disclaimers: MEMO_DISCLAIMERS,
  };
}
